import type { ClientEvent } from "@sazabi/client-sdk-core";
import { computeInputName } from "./element-name";
import { computeSelector } from "./interactions";

export interface InputCaptureOptions {
  emit(event: ClientEvent): void;
}

export interface InputCaptureHandle {
  /** SPA navigation ends any open episodes. */
  notifyNavigation(): void;
  teardown(): void;
}

const IDLE_END_MS = 10_000;
const MAX_TRACKED_EPISODES = 20;

/** Input types that are click-like toggles, not typing surfaces. */
const NON_TEXT_INPUT_TYPES = new Set([
  "button",
  "submit",
  "reset",
  "image",
  "checkbox",
  "radio",
  "range",
  "file",
  "color",
]);

type EpisodeEndReason =
  | "blur"
  | "enter"
  | "change"
  | "idle"
  | "navigation"
  | "hidden"
  | "unload";

interface InputEpisode {
  element: Element;
  selector: string;
  name?: string;
  fieldType: string;
  startUnixMs: number;
  startPerf: number;
  lastInputPerf: number;
  editCount: number;
  pasted: boolean;
}

const editableFieldType = (target: EventTarget | null): string | undefined => {
  if (target instanceof HTMLInputElement) {
    const type = (target.type || "text").toLowerCase();
    return NON_TEXT_INPUT_TYPES.has(type) ? undefined : type;
  }
  if (target instanceof HTMLTextAreaElement) return "textarea";
  if (target instanceof HTMLSelectElement) return "select";
  if (target instanceof HTMLElement && target.isContentEditable) {
    return "contenteditable";
  }
  return undefined;
};

/**
 * Field-interaction episodes: one `input` event per engagement with an
 * editable element, not per keystroke. The event is timestamped at episode
 * START (so the timeline reads causally: typed → the request that followed)
 * and emitted when the episode ends — blur, Enter, ~10s idle, SPA
 * navigation, tab hidden, or teardown.
 *
 * Privacy invariants: `event.data`, field values, selected option text, and
 * key identities are never read (Enter is inspected solely as a boundary and
 * never recorded); no value derivatives, including length. Names come from
 * developer-authored sources only (see element-name.ts).
 */
export const installInputCapture = (
  options: InputCaptureOptions,
): InputCaptureHandle => {
  const episodes = new Map<Element, InputEpisode>();

  const endEpisode = (
    episode: InputEpisode,
    endedBy: EpisodeEndReason,
  ): void => {
    episodes.delete(episode.element);
    try {
      options.emit({
        type: "input",
        body: episode.name
          ? `input "${episode.name}"`
          : `input ${episode.selector}`,
        severity: "INFO",
        timeUnixMs: episode.startUnixMs,
        attributes: {
          "app.widget.id": episode.selector,
          "app.widget.name": episode.name,
          "app.input.field_type": episode.fieldType,
          "app.input.edit_count": episode.editCount,
          "app.input.duration_ms": Math.max(
            0,
            Math.round(episode.lastInputPerf - episode.startPerf),
          ),
          ...(episode.pasted ? { "app.input.pasted": true } : {}),
          "app.input.ended_by": endedBy,
        },
      });
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  const endAll = (endedBy: EpisodeEndReason): void => {
    for (const episode of Array.from(episodes.values())) {
      endEpisode(episode, endedBy);
    }
  };

  const sweepIdle = (now: number): void => {
    for (const episode of Array.from(episodes.values())) {
      if (now - episode.lastInputPerf > IDLE_END_MS) {
        endEpisode(episode, "idle");
      }
    }
  };

  const onInput = (event: Event): void => {
    try {
      const now = performance.now();
      sweepIdle(now);

      const target = event.target;
      const fieldType = editableFieldType(target);
      if (fieldType === undefined || !(target instanceof Element)) {
        return;
      }
      // `change` matters only for selects (option committed): for text
      // fields it fires at commit time and would double-count the episode.
      if (event.type === "change" && fieldType !== "select") {
        return;
      }

      let episode = episodes.get(target);
      if (!episode) {
        if (episodes.size >= MAX_TRACKED_EPISODES) {
          return; // Safety valve; the idle sweep keeps this map tiny.
        }
        episode = {
          element: target,
          selector: computeSelector(target),
          name: computeInputName(target),
          fieldType,
          startUnixMs: Date.now(),
          startPerf: now,
          lastInputPerf: now,
          editCount: 0,
          pasted: false,
        };
        episodes.set(target, episode);
      }

      episode.editCount += 1;
      episode.lastInputPerf = now;
      // Only the paste marker is read off the event — never `data`/values.
      const inputType = (event as InputEvent).inputType;
      if (
        typeof inputType === "string" &&
        inputType.startsWith("insertFromPaste")
      ) {
        episode.pasted = true;
      }

      // A select commits atomically on change; there is no blur to wait for
      // (programmatic/JS-driven selects never focus the element).
      if (event.type === "change" && fieldType === "select") {
        endEpisode(episode, "change");
      }
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  const onFocusOut = (event: Event): void => {
    try {
      const target = event.target;
      if (target instanceof Element) {
        const episode = episodes.get(target);
        if (episode) endEpisode(episode, "blur");
      }
    } catch {
      // Ignore.
    }
  };

  const onKeyDown = (event: KeyboardEvent): void => {
    try {
      // Enter is the only key ever inspected, solely as an episode
      // boundary; key identities are never recorded.
      if (event.key !== "Enter") return;
      const target = event.target;
      if (target instanceof Element) {
        const episode = episodes.get(target);
        if (episode) endEpisode(episode, "enter");
      }
    } catch {
      // Ignore.
    }
  };

  const onVisibilityChange = (): void => {
    if (document.visibilityState === "hidden") {
      endAll("hidden");
    }
  };
  const onPageHide = (): void => {
    endAll("unload");
  };

  document.addEventListener("input", onInput, { capture: true, passive: true });
  // Selects commit through `change`; some drivers/frameworks emit it without
  // a preceding `input`.
  document.addEventListener("change", onInput, {
    capture: true,
    passive: true,
  });
  document.addEventListener("focusout", onFocusOut, {
    capture: true,
    passive: true,
  });
  document.addEventListener("keydown", onKeyDown, {
    capture: true,
    passive: true,
  });
  document.addEventListener("visibilitychange", onVisibilityChange);
  window.addEventListener("pagehide", onPageHide);

  return {
    notifyNavigation() {
      endAll("navigation");
    },
    teardown() {
      document.removeEventListener("input", onInput, { capture: true });
      document.removeEventListener("change", onInput, { capture: true });
      document.removeEventListener("focusout", onFocusOut, { capture: true });
      document.removeEventListener("keydown", onKeyDown, { capture: true });
      document.removeEventListener("visibilitychange", onVisibilityChange);
      window.removeEventListener("pagehide", onPageHide);
      endAll("unload");
    },
  };
};
