import { type ClientEvent, truncateValue } from "@sazabi/client-sdk-core";

export interface ErrorCaptureOptions {
  emit(event: ClientEvent): void;
}

export interface ErrorCaptureHandle {
  teardown(): void;
}

export const installErrorCapture = (
  options: ErrorCaptureOptions,
): ErrorCaptureHandle => {
  const onError = (event: ErrorEvent): void => {
    try {
      const error: unknown = event.error;
      const exceptionType = error instanceof Error ? error.name : "Error";
      const message = event.message || "Unknown error";

      options.emit({
        type: "error",
        body: truncateValue(`${exceptionType}: ${message}`, 512),
        severity: "ERROR",
        timeUnixMs: Date.now(),
        attributes: {
          "exception.type": exceptionType,
          "exception.message": message,
          "exception.stacktrace":
            error instanceof Error ? (error.stack ?? "") : "",
          "app.error.kind": "uncaught",
          "app.error.filename": event.filename || undefined,
          "app.error.lineno": event.lineno || undefined,
          "app.error.colno": event.colno || undefined,
        },
      });
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  const onUnhandledRejection = (event: PromiseRejectionEvent): void => {
    try {
      const reason: unknown = event.reason;
      const isError = reason instanceof Error;
      const exceptionType = isError ? reason.name : "UnhandledRejection";
      const message = isError ? reason.message : String(reason);

      options.emit({
        type: "error",
        body: truncateValue(`${exceptionType}: ${message}`, 512),
        severity: "ERROR",
        timeUnixMs: Date.now(),
        attributes: {
          "exception.type": exceptionType,
          "exception.message": message,
          "exception.stacktrace": isError ? (reason.stack ?? "") : "",
          "app.error.kind": "unhandledrejection",
        },
      });
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  window.addEventListener("error", onError);
  window.addEventListener("unhandledrejection", onUnhandledRejection);

  return {
    teardown() {
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onUnhandledRejection);
    },
  };
};
