import {
  type ClientEvent,
  createPointerTracker,
  type DerivedTap,
  type PointerCaptureConfig,
  type PointerTarget,
  type PointerType,
  type RandomBytes,
} from "@sazabi/client-sdk-core";
import { computeClickName } from "./element-name";

export interface InteractionCaptureOptions {
  emit(event: ClientEvent): void;
  randomBytes: RandomBytes;
  pointer: PointerCaptureConfig;
}

export interface InteractionCaptureHandle {
  /** Navigation counts as a click response for dead-click detection. */
  notifyNavigation(): void;
  teardown(): void;
}

const DEAD_CLICK_TIMEOUT_MS = 800;
const MAX_SELECTOR_LENGTH = 200;

const INTERACTIVE_SELECTOR =
  "a,button,[role=button],input,select,textarea,label,summary,[tabindex],[onclick]";

/** Short, stable-ish selector for an element; never includes text content. */
export const computeSelector = (element: Element): string => {
  const testId = element.getAttribute("data-testid");
  if (testId) {
    return `[data-testid="${testId}"]`;
  }
  if (element.id) {
    return `#${element.id}`;
  }

  const segments: string[] = [];
  let current: Element | null = element;
  while (current && segments.length < 3) {
    let segment = current.tagName.toLowerCase();
    if (current.id) {
      segments.unshift(`#${current.id}`);
      break;
    }
    const classes = Array.from(current.classList).slice(0, 2);
    if (classes.length > 0) {
      segment += `.${classes.join(".")}`;
    }
    segments.unshift(segment);
    current = current.parentElement;
  }
  return segments.join(" > ").slice(0, MAX_SELECTOR_LENGTH);
};

const describeTarget = (
  target: EventTarget | null,
): PointerTarget | undefined => {
  if (!(target instanceof Element)) {
    return undefined;
  }
  return {
    id: computeSelector(target),
    name: computeClickName(target),
    tag: target.tagName.toLowerCase(),
    interactive: target.closest(INTERACTIVE_SELECTOR) !== null,
  };
};

const pointerTypeOf = (event: PointerEvent): PointerType =>
  event.pointerType === "touch" || event.pointerType === "pen"
    ? event.pointerType
    : "mouse";

/**
 * Pointer episodes (the core tracker over DOM pointer events) plus the two
 * signals only the browser can derive: dead clicks, which need a DOM-mutation
 * signal, and keyboard-activated clicks, which produce no pointer contact.
 */
export const installInteractionCapture = (
  options: InteractionCaptureOptions,
): InteractionCaptureHandle => {
  // Monotonic counters, not timestamps. `performance.now()` is coarsened
  // (Chromium clamps it, and more so without cross-origin isolation), and the
  // click -> handler -> microtask -> MutationObserver path finishes well inside
  // one tick. Counters captured at tap time ask the exact question instead:
  // "did anything happen after this tap?", with no dependence on clock
  // resolution.
  let domActivityGeneration = 0;
  let navigationGeneration = 0;
  const pendingDeadClickTimers = new Set<number>();

  const observer = new MutationObserver(() => {
    domActivityGeneration += 1;
  });
  try {
    observer.observe(document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      characterData: true,
    });
  } catch {
    // Without mutation signal, dead clicks are simply never reported.
  }

  const watchForDeadClick = (tap: DerivedTap): void => {
    if (!tap.target?.interactive) return;
    const label = tap.target.name
      ? `"${tap.target.name}"`
      : (tap.target.id ?? "");
    const domGenAtClick = domActivityGeneration;
    const navGenAtClick = navigationGeneration;
    const timer = window.setTimeout(() => {
      pendingDeadClickTimers.delete(timer);
      try {
        // Unchanged counters mean nothing observable followed the tap.
        if (
          domActivityGeneration === domGenAtClick &&
          navigationGeneration === navGenAtClick
        ) {
          options.emit({
            type: "dead_click",
            body: `dead click ${label}`,
            severity: "WARN",
            timeUnixMs: Date.now(),
            attributes: {
              "app.widget.id": tap.target?.id,
              "app.widget.name": tap.target?.name,
              "app.widget.tag": tap.target?.tag,
              "app.pointer.gesture_id": tap.gestureId,
            },
          });
        }
      } catch {
        // Never throw from a timer into the host.
      }
    }, DEAD_CLICK_TIMEOUT_MS);
    pendingDeadClickTimers.add(timer);
  };

  const tracker = createPointerTracker({
    emit: options.emit,
    randomBytes: options.randomBytes,
    sampleIntervalMs: options.pointer.sampleIntervalMs,
    partialIntervalMs: options.pointer.partialIntervalMs,
    onTap: watchForDeadClick,
  });

  const onPointerDown = (event: PointerEvent): void => {
    try {
      tracker.down({
        id: event.pointerId,
        type: pointerTypeOf(event),
        primary: event.isPrimary,
        button: pointerTypeOf(event) === "mouse" ? event.button : undefined,
        x: event.clientX,
        y: event.clientY,
        pressure: event.pressure || undefined,
        target: describeTarget(event.target),
      });
    } catch {
      // Capture failures must never surface to the host.
    }
  };
  const onPointerMove = (event: PointerEvent): void => {
    tracker.move(
      event.pointerId,
      event.clientX,
      event.clientY,
      event.pressure || undefined,
    );
  };
  const onPointerUp = (event: PointerEvent): void => {
    tracker.up(event.pointerId, event.clientX, event.clientY);
  };
  const onPointerCancel = (event: PointerEvent): void => {
    tracker.cancel(event.pointerId);
  };

  // Keyboard activation (Enter/Space on a focused control) and script
  // `click()` calls fire `click` with no pointer contact behind them. They
  // are still taps: the row, the rage detection, and the dead-click watch
  // all apply, with `app.pointer.type: "none"` and no episode.
  const onClick = (event: MouseEvent): void => {
    try {
      if ((event as PointerEvent).pointerType || event.detail !== 0) {
        return;
      }
      tracker.tap({
        x: event.clientX,
        y: event.clientY,
        target: describeTarget(event.target),
      });
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  const listenerOptions: AddEventListenerOptions = {
    capture: true,
    passive: true,
  };
  document.addEventListener("pointerdown", onPointerDown, listenerOptions);
  document.addEventListener("pointermove", onPointerMove, listenerOptions);
  document.addEventListener("pointerup", onPointerUp, listenerOptions);
  document.addEventListener("pointercancel", onPointerCancel, listenerOptions);
  document.addEventListener("click", onClick, listenerOptions);

  return {
    notifyNavigation() {
      navigationGeneration += 1;
    },
    teardown() {
      document.removeEventListener("pointerdown", onPointerDown, {
        capture: true,
      });
      document.removeEventListener("pointermove", onPointerMove, {
        capture: true,
      });
      document.removeEventListener("pointerup", onPointerUp, { capture: true });
      document.removeEventListener("pointercancel", onPointerCancel, {
        capture: true,
      });
      document.removeEventListener("click", onClick, { capture: true });
      tracker.teardown();
      observer.disconnect();
      for (const timer of pendingDeadClickTimers) {
        window.clearTimeout(timer);
      }
      pendingDeadClickTimers.clear();
    },
  };
};
