/**
 * Human-readable element names for timeline events — a pragmatic subset of
 * the ARIA accessible-name computation, biased hard toward developer-authored
 * sources. The bright line: app-authored static text (labels, aria-label,
 * placeholder, button captions) is capturable; user-reflected text (values,
 * selected options, data rendered into the DOM) is not. `data-sazabi-name`
 * overrides any element's reported name; `data-sazabi-mask` on an ancestor
 * suppresses name capture for the whole subtree.
 */

const MAX_NAME_CHARS = 64;
const NAME_ATTRIBUTE = "data-sazabi-name";
const MASK_ATTRIBUTE = "data-sazabi-mask";

/**
 * Click-name eligibility: genuinely interactive elements only. Clicks on
 * plain containers (divs, table cells — where user content lives) get a
 * selector but never text.
 */
const INTERACTIVE_NAME_SELECTOR = [
  "button",
  "a[href]",
  "summary",
  '[role="button"]',
  '[role="link"]',
  '[role="tab"]',
  '[role="menuitem"]',
  '[role="menuitemcheckbox"]',
  '[role="menuitemradio"]',
  '[role="option"]',
  '[role="checkbox"]',
  '[role="switch"]',
  'input[type="submit"]',
  'input[type="button"]',
  'input[type="reset"]',
].join(",");

const normalizeName = (raw: string | null | undefined): string | undefined => {
  if (!raw) return undefined;
  const collapsed = raw.replace(/\s+/g, " ").trim();
  if (!collapsed) return undefined;
  return collapsed.length > MAX_NAME_CHARS
    ? `${collapsed.slice(0, MAX_NAME_CHARS)}…`
    : collapsed;
};

const isMasked = (element: Element): boolean => {
  try {
    return element.closest(`[${MASK_ATTRIBUTE}]`) !== null;
  } catch {
    return true; // Fail closed: no name beats a leaked name.
  }
};

/** Shared dev-authored sources: override attr → aria-label → aria-labelledby. */
const authoredName = (element: Element): string | undefined => {
  const explicit = normalizeName(element.getAttribute(NAME_ATTRIBUTE));
  if (explicit) return explicit;
  const ariaLabel = normalizeName(element.getAttribute("aria-label"));
  if (ariaLabel) return ariaLabel;

  const ids = element.getAttribute("aria-labelledby");
  if (!ids) return undefined;
  return normalizeName(
    ids
      .split(/\s+/)
      .map((id) => document.getElementById(id)?.textContent ?? "")
      .join(" "),
  );
};

/**
 * Name for an input/textarea/select/contenteditable — developer-authored
 * sources only; the field's value and (for selects) the chosen option text
 * are never read.
 */
export const computeInputName = (element: Element): string | undefined => {
  try {
    if (isMasked(element)) return undefined;

    const named = authoredName(element);
    if (named) return named;

    if (
      element instanceof HTMLInputElement ||
      element instanceof HTMLTextAreaElement ||
      element instanceof HTMLSelectElement
    ) {
      for (const label of Array.from(element.labels ?? [])) {
        const labelText = normalizeName(label.textContent);
        if (labelText) return labelText;
      }
    }

    const placeholder = normalizeName(element.getAttribute("placeholder"));
    if (placeholder) return placeholder;
    return normalizeName(element.getAttribute("name"));
  } catch {
    return undefined;
  }
};

/**
 * Name for a click target: nearest interactive ancestor's accessible-ish
 * name. Residual risk is labels that interpolate user data ("Delete 'My
 * Project'") — that is app-authored markup, capped at 64 chars, and
 * suppressible via `data-sazabi-mask` / overridable via `data-sazabi-name`.
 */
export const computeClickName = (target: Element): string | undefined => {
  try {
    const interactive = target.closest(INTERACTIVE_NAME_SELECTOR);
    if (!interactive || isMasked(interactive)) return undefined;

    const named = authoredName(interactive);
    if (named) return named;

    if (interactive instanceof HTMLInputElement) {
      // submit/button/reset inputs: the value attribute IS the caption.
      return normalizeName(interactive.getAttribute("value"));
    }
    return normalizeName(interactive.textContent);
  } catch {
    return undefined;
  }
};
