import { monotonicNow } from "./clock";
import { newPrefixedId, type RandomBytes } from "./random";
import type { ClientEvent, EventAttributes } from "./types";

/**
 * Pointer episodes: one row per contact from down to up, for mouse, touch,
 * and pen alike. A binding feeds raw contacts in (DOM pointer events in the
 * browser, the responder's touch arrays on mobile) and the tracker emits the
 * episode rows plus the derived `click` and `rage_click` rows. Movement is
 * sampled, never streamed: a position sample every `sampleIntervalMs` is
 * packed into the row, and a contact that outlives `partialIntervalMs` emits
 * a partial row at that cadence so a long scroll is not a blind spot.
 */

export type PointerType = "mouse" | "touch" | "pen";

export interface PointerTarget {
  /** Developer-authored name for the widget under the pointer, if any. */
  name?: string;
  /** Stable-ish identifier: a selector on the web, a component path on mobile. */
  id?: string;
  /** Element tag or component kind. */
  tag?: string;
  /** Whether a tap here is on something that should respond. */
  interactive: boolean;
}

export interface PointerContact {
  id: number | string;
  type: PointerType;
  primary: boolean;
  x: number;
  y: number;
  pressure?: number;
  /**
   * The button that started a mouse contact (DOM `button`: 0 primary, 1
   * auxiliary, 2 secondary). Absent for touch and pen. Only a primary-button
   * contact can derive a click: a short right or middle press is an episode
   * without a tap, matching the host's `contextmenu` and `auxclick`.
   */
  button?: number;
  target?: PointerTarget;
}

export interface DerivedTap {
  x: number;
  y: number;
  target?: PointerTarget;
  /** Absent for a tap no contact produced (keyboard activation, script). */
  gestureId?: string;
}

export interface PointerTrackerOptions {
  emit(event: ClientEvent): void;
  randomBytes: RandomBytes;
  /** Spacing of packed position samples. Default 1000. */
  sampleIntervalMs?: number;
  /** Cadence of partial rows for long contacts. Default 10000. */
  partialIntervalMs?: number;
  /** Every derived tap, so a binding can run its own dead-tap detection. */
  onTap?(tap: DerivedTap): void;
}

export interface PointerTracker {
  down(contact: PointerContact): void;
  move(id: number | string, x: number, y: number, pressure?: number): void;
  up(id: number | string, x: number, y: number): void;
  cancel(id: number | string): void;
  /**
   * A click that no pointer contact produced: keyboard activation or a
   * script calling `click()`. Emits the `click` row and runs the same rage
   * and dead-tap derivation, with no episode behind it.
   */
  tap(tap: { x: number; y: number; target?: PointerTarget }): void;
  teardown(): void;
}

const DEFAULT_SAMPLE_INTERVAL_MS = 1_000;
const DEFAULT_PARTIAL_INTERVAL_MS = 10_000;
const TAP_MAX_DISTANCE_PX = 10;
const TAP_MAX_DURATION_MS = 500;
const RAGE_WINDOW_MS = 1_000;
const RAGE_RADIUS_PX = 30;
const RAGE_TAP_COUNT = 4;
const MAX_OPEN_CONTACTS = 10;

/**
 * `cancel` means the contact stopped reaching us before release: the host
 * took the gesture for itself (a native or browser scroll, a pager, a
 * drawer, a system gesture) or the release was lost. The finger may still be
 * moving, so the row ends where the host took over, not where it lifted.
 */
type EndedBy = "up" | "cancel" | "teardown";

interface OpenContact {
  contact: PointerContact;
  gestureId: string;
  startUnixMs: number;
  startPerf: number;
  lastSamplePerf: number;
  lastX: number;
  lastY: number;
  /** Farthest the contact strayed from its start, so a drag that returns is still a drag. */
  maxDistance: number;
  maxPressure?: number;
  maxConcurrent: number;
  /** Samples since the last emitted row, as `t:x,y`. */
  path: string[];
  sampleCount: number;
  partialTimer?: ReturnType<typeof setTimeout>;
}

interface RecentTap {
  time: number;
  x: number;
  y: number;
}

interface TapDetails {
  x: number;
  y: number;
  target?: PointerTarget;
  /** `none` when no contact produced the click. */
  pointerType: PointerType | "none";
  gestureId?: string;
  timeUnixMs: number;
}

const distance = (x0: number, y0: number, x1: number, y1: number): number =>
  Math.hypot(x1 - x0, y1 - y0);

const targetAttributes = (target?: PointerTarget): EventAttributes => ({
  "app.widget.id": target?.id,
  "app.widget.name": target?.name,
  "app.widget.tag": target?.tag,
});

export const createPointerTracker = (
  options: PointerTrackerOptions,
): PointerTracker => {
  const sampleIntervalMs =
    options.sampleIntervalMs ?? DEFAULT_SAMPLE_INTERVAL_MS;
  const partialIntervalMs =
    options.partialIntervalMs ?? DEFAULT_PARTIAL_INTERVAL_MS;
  const open = new Map<number | string, OpenContact>();
  const recentTaps: RecentTap[] = [];
  // Not 0: an early first-second burst must still report.
  let rageReportedAt = Number.NEGATIVE_INFINITY;
  let currentGestureId: string | undefined;

  const sample = (entry: OpenContact, now: number): void => {
    entry.path.push(
      `${Math.round(now - entry.startPerf)}:${Math.round(entry.lastX)},${Math.round(entry.lastY)}`,
    );
    entry.sampleCount += 1;
    entry.lastSamplePerf = now;
  };

  const emitRow = (
    entry: OpenContact,
    now: number,
    endedBy: EndedBy | undefined,
  ): void => {
    const { contact } = entry;
    const partial = endedBy === undefined;
    const durationMs = Math.round(now - entry.startPerf);
    const travelled = distance(contact.x, contact.y, entry.lastX, entry.lastY);
    try {
      options.emit({
        type: "pointer",
        body: `pointer ${contact.type} ${durationMs}ms ${Math.round(travelled)}px${partial ? " (ongoing)" : ""}`,
        severity: "INFO",
        // Final rows sit at the contact's start so the timeline reads
        // causally; partial rows are progress marks and sit where they fire.
        timeUnixMs: partial ? Date.now() : entry.startUnixMs,
        attributes: {
          "app.pointer.id": String(contact.id),
          "app.pointer.type": contact.type,
          "app.pointer.primary": contact.primary,
          "app.pointer.gesture_id": entry.gestureId,
          "app.screen.coordinate.x": Math.round(contact.x),
          "app.screen.coordinate.y": Math.round(contact.y),
          "app.pointer.end.x": Math.round(entry.lastX),
          "app.pointer.end.y": Math.round(entry.lastY),
          "app.pointer.distance": Math.round(travelled),
          "app.pointer.duration_ms": durationMs,
          "app.pointer.pressure": entry.maxPressure,
          "app.pointer.concurrent": entry.maxConcurrent,
          "app.pointer.path": entry.path.join(";") || undefined,
          "app.pointer.sample_count": entry.sampleCount,
          "app.pointer.partial": partial ? true : undefined,
          "app.pointer.ended_by": endedBy,
          ...targetAttributes(contact.target),
        },
      });
    } catch {
      // Emitting must never throw into the host.
    }
    entry.path = [];
  };

  const schedulePartial = (entry: OpenContact): void => {
    entry.partialTimer = setTimeout(() => {
      entry.partialTimer = undefined;
      try {
        const now = monotonicNow();
        if (now - entry.lastSamplePerf >= sampleIntervalMs) {
          sample(entry, now);
        }
        emitRow(entry, now, undefined);
        schedulePartial(entry);
      } catch {
        // Never throw from a timer into the host.
      }
    }, partialIntervalMs);
  };

  const emitTap = (tap: TapDetails, now: number): void => {
    const name = tap.target?.name;
    const label = name
      ? `"${name}"`
      : (tap.target?.id ?? `${Math.round(tap.x)},${Math.round(tap.y)}`);
    const tapAttributes: EventAttributes = {
      ...targetAttributes(tap.target),
      "app.pointer.type": tap.pointerType,
      "app.pointer.gesture_id": tap.gestureId,
      "app.screen.coordinate.x": Math.round(tap.x),
      "app.screen.coordinate.y": Math.round(tap.y),
    };

    try {
      options.emit({
        type: "click",
        body: `click ${label}`,
        severity: "INFO",
        timeUnixMs: tap.timeUnixMs,
        attributes: tapAttributes,
      });
    } catch {
      // Never throw into the host.
    }

    // Rage tap: repeated taps in a tight radius within the window.
    recentTaps.push({ time: now, x: tap.x, y: tap.y });
    while (
      recentTaps.length > 0 &&
      now - (recentTaps[0] as RecentTap).time > RAGE_WINDOW_MS
    ) {
      recentTaps.shift();
    }
    const clustered = recentTaps.filter(
      (recent) =>
        Math.abs(recent.x - tap.x) <= RAGE_RADIUS_PX &&
        Math.abs(recent.y - tap.y) <= RAGE_RADIUS_PX,
    );
    if (
      clustered.length >= RAGE_TAP_COUNT &&
      now - rageReportedAt > RAGE_WINDOW_MS
    ) {
      rageReportedAt = now;
      try {
        options.emit({
          type: "rage_click",
          body: `rage click ${label}`,
          severity: "WARN",
          timeUnixMs: Date.now(),
          attributes: {
            ...tapAttributes,
            "app.pointer.tap_count": clustered.length,
          },
        });
      } catch {
        // Never throw into the host.
      }
    }

    try {
      options.onTap?.({
        x: tap.x,
        y: tap.y,
        target: tap.target,
        gestureId: tap.gestureId,
      });
    } catch {
      // A binding's tap hook must never break capture.
    }
  };

  const deriveTap = (entry: OpenContact, now: number): void => {
    const { contact } = entry;
    if (
      entry.maxConcurrent !== 1 ||
      (contact.button ?? 0) !== 0 ||
      now - entry.startPerf > TAP_MAX_DURATION_MS ||
      entry.maxDistance > TAP_MAX_DISTANCE_PX
    ) {
      return;
    }
    emitTap(
      {
        x: entry.lastX,
        y: entry.lastY,
        target: contact.target,
        pointerType: contact.type,
        gestureId: entry.gestureId,
        timeUnixMs: entry.startUnixMs,
      },
      now,
    );
  };

  const end = (
    entry: OpenContact,
    x: number,
    y: number,
    endedBy: EndedBy,
  ): void => {
    const now = monotonicNow();
    open.delete(entry.contact.id);
    if (entry.partialTimer !== undefined) {
      clearTimeout(entry.partialTimer);
      entry.partialTimer = undefined;
    }
    entry.lastX = x;
    entry.lastY = y;
    entry.maxDistance = Math.max(
      entry.maxDistance,
      distance(entry.contact.x, entry.contact.y, x, y),
    );
    emitRow(entry, now, endedBy);
    if (endedBy === "up") {
      deriveTap(entry, now);
    }
    if (open.size === 0) {
      currentGestureId = undefined;
    }
  };

  return {
    down(contact) {
      try {
        const stale = open.get(contact.id);
        if (stale) {
          // A new down for an open id means its up or cancel was lost (a
          // release outside the window, a native context menu): close it, or
          // the id is blocked forever and its partial timer never stops.
          end(stale, stale.lastX, stale.lastY, "cancel");
        }
        if (open.size >= MAX_OPEN_CONTACTS) {
          return;
        }
        const now = monotonicNow();
        // A contact that lands while others are down joins their gesture.
        if (open.size === 0 || currentGestureId === undefined) {
          currentGestureId = newPrefixedId(options.randomBytes, "gest");
        }
        const concurrent = open.size + 1;
        for (const other of open.values()) {
          other.maxConcurrent = Math.max(other.maxConcurrent, concurrent);
        }
        const entry: OpenContact = {
          contact,
          gestureId: currentGestureId,
          startUnixMs: Date.now(),
          startPerf: now,
          lastSamplePerf: now,
          lastX: contact.x,
          lastY: contact.y,
          maxDistance: 0,
          maxPressure: contact.pressure,
          maxConcurrent: concurrent,
          path: [],
          sampleCount: 0,
        };
        sample(entry, now);
        open.set(contact.id, entry);
        schedulePartial(entry);
      } catch {
        // Capture failures must never surface to the host.
      }
    },
    move(id, x, y, pressure) {
      try {
        const entry = open.get(id);
        if (!entry) return;
        entry.lastX = x;
        entry.lastY = y;
        entry.maxDistance = Math.max(
          entry.maxDistance,
          distance(entry.contact.x, entry.contact.y, x, y),
        );
        if (pressure !== undefined) {
          entry.maxPressure = Math.max(entry.maxPressure ?? 0, pressure);
        }
        const now = monotonicNow();
        if (now - entry.lastSamplePerf >= sampleIntervalMs) {
          sample(entry, now);
        }
      } catch {
        // Ignore.
      }
    },
    up(id, x, y) {
      try {
        const entry = open.get(id);
        if (entry) end(entry, x, y, "up");
      } catch {
        // Ignore.
      }
    },
    cancel(id) {
      try {
        const entry = open.get(id);
        if (entry) end(entry, entry.lastX, entry.lastY, "cancel");
      } catch {
        // Ignore.
      }
    },
    tap(tap) {
      try {
        emitTap(
          {
            x: tap.x,
            y: tap.y,
            target: tap.target,
            pointerType: "none",
            timeUnixMs: Date.now(),
          },
          monotonicNow(),
        );
      } catch {
        // Ignore.
      }
    },
    teardown() {
      for (const entry of Array.from(open.values())) {
        try {
          end(entry, entry.lastX, entry.lastY, "teardown");
        } catch {
          // Best-effort.
        }
      }
      open.clear();
      recentTaps.length = 0;
    },
  };
};
