import type { BeforeSend, ClientEvent } from "./types";

/**
 * The host's `beforeSend` hook, run so that it can never break the SDK: a
 * hook that throws or returns something other than an event drops the event
 * (a hook that redacts must not fail open) and warns once per reason. An
 * event captured synchronously while the hook runs (a `log()` or
 * `addEvent()` call inside it) is dropped rather than sent around the hook
 * or fed back into it, so a hook can never recurse. A request the hook
 * starts completes later and produces an ordinary network event the hook
 * sees like any other; the hook is responsible for excluding it.
 */
export const createBeforeSendGate = (
  hook: BeforeSend | undefined,
  warnOnce: (warning: { reason: string; message: string }) => void,
): ((event: ClientEvent) => ClientEvent | null) => {
  if (!hook) {
    return (event) => event;
  }
  let running = false;
  return (event) => {
    if (running) {
      warnOnce({
        reason: "before_send_nested",
        message:
          "an event was captured while beforeSend was running; nested events are dropped.",
      });
      return null;
    }
    running = true;
    let result: ClientEvent | null;
    try {
      result = hook(event);
    } catch (error) {
      warnOnce({
        reason: "before_send_threw",
        message: `beforeSend threw (${error instanceof Error ? error.message : String(error)}); the event was dropped.`,
      });
      return null;
    } finally {
      running = false;
    }
    if (result === null) {
      return null;
    }
    if (
      typeof result !== "object" ||
      typeof result.type !== "string" ||
      typeof result.body !== "string" ||
      typeof result.severity !== "string" ||
      typeof result.timeUnixMs !== "number" ||
      typeof result.attributes !== "object" ||
      result.attributes === null
    ) {
      warnOnce({
        reason: "before_send_invalid",
        message:
          "beforeSend must return the event or null; the event was dropped.",
      });
      return null;
    }
    return result;
  };
};
