import {
  createBeforeSendGate,
  type ClientEvent,
  createRandomBytes,
  createSdkHealthReporter,
  createSessionManager,
  createTraceContextManager,
  createTransport,
  encodeLogRecord,
  type EventAttributes,
  type EventSeverity,
  flattenAttributes,
  installConsoleCapture,
  isActiveInjectionTarget,
  isUnderBase,
  redactUrl,
  resolveIntakeEndpoint,
} from "@sazabi/client-sdk-core";
import { installErrorCapture } from "./errors";
import {
  createSafeStorage,
  isOffline,
  isReactNativeHost,
  isSameOrigin,
  resolveUrl,
} from "./host";
import { type InputCaptureHandle, installInputCapture } from "./input-capture";
import { installInteractionCapture } from "./interactions";
import {
  installNavigationCapture,
  uninstallNavigationPatches,
} from "./navigation";
import { installNetworkCapture, uninstallNetworkPatches } from "./network";
import { installResourceObserver } from "./resource-observer";
import type { BrowserSdkConfig, NetworkCaptureConfig } from "./types";
import { SDK_CONSOLE_PREFIX, SDK_NAME, SDK_VERSION } from "./version";

export type {
  AttributeValue,
  BeforeSend,
  BrowserSdkConfig,
  ClientEvent,
  ClientEventType,
  ConsoleCaptureConfig,
  ConsoleCaptureLevel,
  EventAttributes,
  EventSeverity,
  InputCaptureConfig,
  NetworkCaptureConfig,
  PointerCaptureConfig,
} from "./types";
export { SDK_VERSION } from "./version";

const DEFAULT_FLUSH_INTERVAL_MS = 5_000;
const DEFAULT_MAX_BATCH_BYTES = 57_344;
const DEFAULT_MAX_QUEUED_EVENTS = 500;
/**
 * Platform request-id response headers probed for `app.network.request_id`,
 * in priority order: generic first, then common CDN/PaaS edges.
 */
const DEFAULT_REQUEST_ID_HEADERS = [
  "x-request-id",
  "cf-ray",
  "x-vercel-id",
  "x-amz-cf-id",
  "fly-request-id",
];

interface SdkInstance {
  identify(distinctId: string, traits?: Record<string, unknown>): void;
  reset(): void;
  addEvent(name: string, attributes?: Record<string, unknown>): void;
  log(
    severity: EventSeverity,
    message: string,
    metadata?: Record<string, unknown>,
  ): void;
  flush(): Promise<void>;
  shutdown(): Promise<void>;
}

interface PendingIdentity {
  distinctId: string;
  traits?: Record<string, unknown>;
}

let instance: SdkInstance | undefined;
let initialized = false;
let pendingIdentity: PendingIdentity | undefined;
let pendingReset = false;

const start = (config: BrowserSdkConfig): void => {
  // Bound before capture activates. Under `register` this may already be the
  // dormant wrapper; intake URLs take its internal passthrough branch, so
  // transport traffic never recurses into capture either way.
  const prePatchFetch = window.fetch.bind(window);

  // Validated in init(); the endpoint carries its own credential when the URL
  // is a keyed intake host.
  const endpoint = resolveIntakeEndpoint(config);
  if (!endpoint) {
    return;
  }
  const intakeUrl = `${endpoint.baseUrl}/v1/logs`;
  const randomBytes = createRandomBytes();

  const session = createSessionManager({
    store: createSafeStorage(() => window.localStorage),
    windowStore: createSafeStorage(() => window.sessionStorage),
    randomBytes,
  });
  // Apply buffered identity before any capture emits, so even the initial
  // navigation event carries the identity claimed while consent was pending.
  if (pendingReset) {
    session.reset();
    pendingReset = false;
  }
  const appliedPendingIdentity = pendingIdentity;
  pendingIdentity = undefined;
  if (appliedPendingIdentity) {
    session.setDistinctId(appliedPendingIdentity.distinctId);
  }

  const transport = createTransport({
    url: intakeUrl,
    publicKey: endpoint.publicKey,
    resourceAttributes: {
      "service.name": config.serviceName,
      "service.version": config.serviceVersion,
      "deployment.environment": config.environment,
      "telemetry.sdk.name": SDK_NAME,
      "telemetry.sdk.version": SDK_VERSION,
      "telemetry.sdk.language": "webjs",
      "browser.user_agent": navigator.userAgent,
      "browser.language": navigator.language,
    },
    scope: { name: SDK_NAME, version: SDK_VERSION },
    // The core types `signal` structurally (no DOM lib); the real fetch takes an AbortSignal.
    fetchImpl: (url, init) => prePatchFetch(url, init as RequestInit),
    flushIntervalMs: config.flushIntervalMs ?? DEFAULT_FLUSH_INTERVAL_MS,
    maxBatchBytes: config.maxBatchBytes ?? DEFAULT_MAX_BATCH_BYTES,
    maxQueuedEvents: config.maxQueuedEvents ?? DEFAULT_MAX_QUEUED_EVENTS,
    // The prefix keeps the console mirror from recording the SDK's own line.
    warn: (message) => console.warn(`${SDK_CONSOLE_PREFIX} ${message}`),
    // The intake refused a batch, or was unreachable for a while: one
    // `sdk_health` row per condition per page (defined below; the transport
    // reports only from settled uploads, after start() returns). An upload
    // settling after shutdown() reports nothing: the row would be dropped,
    // and emitting it would still touch the session store.
    onHealth: (report) => {
      if (!stopped) reportHealth(report);
    },
  });
  let stopped = false;

  const networkConfig: NetworkCaptureConfig = config.network ?? {};
  // The page URL is recorded under the same rule as captured request URLs:
  // a magic-link token or OAuth code in the address bar never leaves the
  // device in plain text.
  const redactPageUrl = (url: string): string =>
    redactUrl(url, networkConfig.redactQueryParams);

  const warnedBeforeSend = new Set<string>();
  const warnBeforeSendOnce = (warning: {
    reason: string;
    message: string;
  }): void => {
    if (warnedBeforeSend.has(warning.reason)) return;
    warnedBeforeSend.add(warning.reason);
    const { message } = warning;
    console.warn(`${SDK_CONSOLE_PREFIX} ${message}`);
  };
  const beforeSend = createBeforeSendGate(
    config.beforeSend,
    warnBeforeSendOnce,
  );

  const emit = (captured: ClientEvent): void => {
    try {
      session.touch();
      const event = beforeSend(captured);
      if (!event) {
        return;
      }
      const base: EventAttributes = {
        "app.event_type": event.type,
        "session.id": session.getSessionId(),
        "session.window_id": session.getWindowId(),
        "session.distinct_id": session.getDistinctId(),
        "app.screen.url": redactPageUrl(window.location.href),
        "derived.source": "sdk",
      };
      transport.enqueue(encodeLogRecord(event, base));
    } catch {
      // Emitting must never throw into the host.
    }
  };

  // The SDK's own delivery health as `sdk_health` rows, at most one per
  // condition per page, so a refused health row is never reported again.
  const reportHealth = createSdkHealthReporter(emit);

  // Scoped to the resolved base, proxy path prefix included: a proxy sharing
  // an origin with the customer's own API must not suppress their traffic.
  // Matched by parsed origin and whole path segments, never a string prefix.
  const isInternalUrl = (url: string): boolean =>
    isUnderBase({ url, base: endpoint.baseUrl });

  // Guards event construction (attribute flattening can throw on exotic
  // input); emit() itself already guards delivery.
  const safeEmitEvent = (build: () => ClientEvent): void => {
    try {
      emit(build());
    } catch {
      // Never throw into the host.
    }
  };

  const teardowns: Array<() => void> = [];

  const errorCapture = installErrorCapture({ emit });
  teardowns.push(() => errorCapture.teardown());

  const interactions = installInteractionCapture({
    emit,
    randomBytes,
    pointer: config.pointer?.capture === false ? {} : (config.pointer ?? {}),
  });
  if (config.pointer?.capture !== false) {
    teardowns.push(() => interactions.teardown());
  } else {
    interactions.teardown();
  }

  let inputCapture: InputCaptureHandle | undefined;
  if (config.input?.capture !== false) {
    inputCapture = installInputCapture({ emit });
    teardowns.push(() => inputCapture?.teardown());
  }

  const navigation = installNavigationCapture({
    emit,
    redactUrl: redactPageUrl,
    onNavigate: () => {
      interactions.notifyNavigation();
      inputCapture?.notifyNavigation();
    },
  });
  teardowns.push(() => navigation.teardown());

  if (config.console?.capture !== false) {
    const consoleCapture = installConsoleCapture({
      emit,
      levels: config.console?.levels ?? ["error", "warn"],
      selfPrefix: SDK_CONSOLE_PREFIX,
    });
    teardowns.push(() => consoleCapture.teardown());
  }

  const networkCapture = networkConfig.capture ?? true;
  const propagateTraceContext = networkConfig.propagateTraceContext ?? true;
  if (networkCapture || propagateTraceContext) {
    const network = installNetworkCapture({
      emit,
      traceContext: createTraceContextManager({
        sampledFlag: networkConfig.sampledFlag ?? false,
        randomBytes,
      }),
      capture: networkCapture,
      propagateTraceContext,
      allowlist: networkConfig.allowlist ?? [],
      redactQueryParams: networkConfig.redactQueryParams,
      requestIdHeaders:
        networkConfig.requestIdHeaders ?? DEFAULT_REQUEST_ID_HEADERS,
      isInternalUrl,
      resolveUrl,
      isDefaultInjectionTarget: isSameOrigin,
      displayOrigin: window.location.origin,
      isOffline,
    });
    teardowns.push(() => network.teardown());
  }

  if (networkCapture && networkConfig.resourceFallback !== false) {
    const resourceObserver = installResourceObserver({
      emit,
      isInternalUrl,
      isInjectionTarget: isActiveInjectionTarget,
      redactQueryParams: networkConfig.redactQueryParams,
    });
    teardowns.push(() => resourceObserver.teardown());
  }

  // Visibility is the browser's lifecycle: hidden is the unload flush point
  // (keepalive lets the batch outlive the page) and both edges are timeline
  // boundaries. pagehide covers bfcache navigations.
  const emitLifecycle = (state: "active" | "background"): void => {
    safeEmitEvent(() => ({
      type: "lifecycle",
      body: `lifecycle ${state}`,
      severity: "INFO",
      timeUnixMs: Date.now(),
      attributes: { "app.lifecycle.state": state },
    }));
  };
  const onVisibilityChange = (): void => {
    if (document.visibilityState === "hidden") {
      emitLifecycle("background");
      void transport.flush({ keepalive: true });
    } else {
      emitLifecycle("active");
    }
  };
  const onPageHide = (): void => {
    void transport.flush({ keepalive: true });
  };
  document.addEventListener("visibilitychange", onVisibilityChange);
  window.addEventListener("pagehide", onPageHide);
  teardowns.push(() => {
    document.removeEventListener("visibilitychange", onVisibilityChange);
    window.removeEventListener("pagehide", onPageHide);
  });

  instance = {
    identify(distinctId, traits) {
      safeEmitEvent(() => {
        session.setDistinctId(distinctId);
        return {
          type: "custom",
          body: `identify ${distinctId}`,
          severity: "INFO",
          timeUnixMs: Date.now(),
          attributes: {
            "app.custom.name": "identify",
            ...(traits ? flattenAttributes(traits, "custom") : {}),
          },
        };
      });
    },
    reset() {
      try {
        session.reset();
      } catch {
        // Never throw into the host.
      }
    },
    addEvent(name, attributes) {
      safeEmitEvent(() => ({
        type: "custom",
        body: `custom ${name}`,
        severity: "INFO",
        timeUnixMs: Date.now(),
        attributes: {
          "app.custom.name": name,
          ...(attributes ? flattenAttributes(attributes, "custom") : {}),
        },
      }));
    },
    log(severity, message, metadata) {
      safeEmitEvent(() => ({
        type: "log",
        body: message,
        severity,
        timeUnixMs: Date.now(),
        // Raw-key flattening (no prefix) for parity with app loggers,
        // so existing log queries keep their attribute names.
        attributes: metadata ? flattenAttributes(metadata) : {},
      }));
    },
    flush() {
      return transport.flush();
    },
    async shutdown() {
      for (const teardown of teardowns.reverse()) {
        try {
          teardown();
        } catch {
          // Teardown must be best-effort.
        }
      }
      // Deactivation above leaves dormant patches; full shutdown restores
      // the natives (when still ours).
      uninstallNetworkPatches();
      uninstallNavigationPatches();
      stopped = true;
      await transport.shutdown();
    },
  };

  // The identify event for a pre-consent identify() is emitted only now that
  // capture exists; the id itself was applied to the session earlier.
  if (appliedPendingIdentity) {
    instance.identify(
      appliedPendingIdentity.distinctId,
      appliedPendingIdentity.traits,
    );
  }
};

/**
 * Initialize the SDK. Idempotent: repeat calls are ignored. When `consent`
 * is provided, nothing new is installed (no listeners, no patches, no
 * network) until it resolves true; on false (or a throw) the SDK stays
 * dormant. (Patches pre-installed by `@sazabi/browser/register` exist
 * but remain inert passthroughs until activation.)
 */
export const init = (config: BrowserSdkConfig): void => {
  if (typeof window === "undefined") {
    return; // SSR: nothing to capture.
  }
  if (isReactNativeHost()) {
    // Developer-facing: the mobile SDK owns this host. Warn once, install
    // nothing; every public call below stays a no-op.
    console.warn(
      `${SDK_CONSOLE_PREFIX} this is a React Native app; use @sazabi/react-native instead. SDK disabled.`,
    );
    return;
  }
  if (initialized) {
    return;
  }
  initialized = true;

  if (!config.serviceName || !resolveIntakeEndpoint(config)) {
    // Developer-facing misconfiguration: warn once, never throw.
    console.warn(
      `${SDK_CONSOLE_PREFIX} init() requires intakeUrl and serviceName; SDK disabled. ` +
        "Pass publicKey too if the intake URL is a proxy that carries no key.",
    );
    return;
  }

  if (config.consent === undefined) {
    start(config);
    return;
  }

  try {
    void Promise.resolve(config.consent())
      .then((granted) => {
        if (granted === true) {
          start(config);
        }
      })
      .catch(() => {
        // Consent evaluation failed: stay dormant.
      });
  } catch {
    // Synchronous throw from consent(): stay dormant.
  }
};

/** Set the client-asserted user identity (`session.distinct_id`). */
export const identify = (
  distinctId: string,
  traits?: Record<string, unknown>,
): void => {
  if (instance) {
    instance.identify(distinctId, traits);
  } else {
    // Buffer identity across a pending consent gate; the identify event is
    // emitted when capture starts.
    pendingIdentity = { distinctId, traits };
  }
};

/**
 * Logout: clear the client-asserted identity and rotate both session and
 * window ids, so later activity on this device never threads into the
 * previous user's timeline.
 */
export const reset = (): void => {
  if (instance) {
    instance.reset();
  } else {
    pendingReset = true;
    pendingIdentity = undefined;
  }
};

/** Emit a custom mark into the session event stream. */
export const addEvent = (
  name: string,
  attributes?: Record<string, unknown>,
): void => {
  instance?.addEvent(name, attributes);
};

/**
 * Emit an application log line (`app.event_type: "log"`) with session context
 * attached. Drops silently before init/consent, like all capture.
 */
export const log = (
  severity: EventSeverity,
  message: string,
  metadata?: Record<string, unknown>,
): void => {
  instance?.log(severity, message, metadata);
};

/** Force-flush queued events. */
export const flush = async (): Promise<void> => {
  await instance?.flush();
};

/** Tear down all patches/listeners (restoring originals) and flush. */
export const shutdown = async (): Promise<void> => {
  const active = instance;
  instance = undefined;
  initialized = false;
  pendingIdentity = undefined;
  pendingReset = false;
  await active?.shutdown();
};
